export const LEARNING_ITEM_INDEX: Record<string, [display: string, href: string]> = Object.fromEntries(Object.entries(RAW).map(([k, v]) => {
  if (typeof v === "string") return [k, [v, `/learn/${k.slice(7)}`]]
  const [d, t] = v
  if (typeof t === "number") {
    if (k.startsWith("vocab:")) return [k, [d, `/vocabulary?level=${VLEVELS[t]}&item=${encodeURIComponent(k.slice(6))}`]]
    return [k, [d, `/learn/${SLUGS[t]}`]]
  }
  if (k.startsWith("grammar:") && !t.startsWith("/")) return [k, [d, `/grammar?level=${t}&item=${encodeURIComponent(k.slice(8))}`]]
  return [k, [d, t]]
}))
